/* From Uiverse.io by boryanakrasteva - Tags: button, delete */
.__UIV_SCOPE__ .btn {
  background-color: transparent;
  position: relative;
  border: none;
}

.__UIV_SCOPE__ .btn::after {
  content: 'delete';
  position: absolute;
  top: -130%;
  left: 50%;
  transform: translateX(-50%);
  width: fit-content;
  height: fit-content;
  background-color: rgb(168, 7, 7);
  padding: 4px 8px;
  border-radius: 5px;
  transition: .2s linear;
  transition-delay: .2s;
  color: white;
  text-transform: uppercase;
  font-size: 12px;
  opacity: 0;
  visibility: hidden;
}

.__UIV_SCOPE__ .icon {
  transform: scale(1.2);
  transition: .2s linear;
}

.__UIV_SCOPE__ .btn:hover > .icon {
  transform: scale(1.5);
}

.__UIV_SCOPE__ .btn:hover > .icon path {
  fill: rgb(168, 7, 7);
}

.__UIV_SCOPE__ .btn:hover::after {
  visibility: visible;
  opacity: 1;
  top: -160%;
}
